## Prompt Cache / Slot Reuse — Code Walkthrough

### 1. Slot Selection: `get_available_slot()` (server-context.cpp:1530)

Three strategies in order:

**A. Explicit slot ID** — if `task.id_slot != -1`:
```cpp
if (task.id_slot != -1) {
    ret = get_slot_by_id(task.id_slot);
    if (ret) {
        SLT_INF(*ret, "selected slot by id (%d)\n", task.id_slot);
    }
}
```

**B. LCP similarity matching** — finds the slot with the highest Longest Common Prefix overlap:
```cpp
if (slot_prompt_similarity != 0.0f) {
    float sim_best = 0;

    for (server_slot & slot : slots) {
        if (task.id_slot != -1 && slot.id != task.id_slot) {
            continue;
        }
        if (slot.is_processing()) {
            continue;
        }
        const auto & tokens = slot.prompt.tokens;
        if (tokens.empty()) {
            continue;
        }

        // fraction of the LCP length with respect to the input prompt length
        const float sim_cur = float(tokens.get_common_prefix(task.tokens)) / task.tokens.size();

        if (sim_cur > sim_best && sim_cur > slot_prompt_similarity) {
            sim_best = sim_cur;
            ret = &slot;
        }
    }

    if (ret != nullptr) {
        const float f_keep = (sim_best*task.tokens.size()) / ret->prompt.tokens.size();

        SLT_INF(*ret, "selected slot by LCP similarity, sim_best = %.3f (> %.3f thold), f_keep = %.3f\n",
                sim_best, slot_prompt_similarity, f_keep);

        // if we are about to lose a large portion of the existing context - save it
        if (f_keep < 0.5f) {
            update_cache = true;
        }
    }
}
```

**C. LRU fallback** — picks the least-recently-used idle slot:
```cpp
if (ret == nullptr) {
    int64_t t_last = -1;
    for (server_slot & slot : slots) {
        if (slot.is_processing()) continue;
        if (!ret || slot.t_last_used <= t_last) {
            t_last = slot.t_last_used;
            ret = &slot;
        }
    }
    if (ret != nullptr) {
        SLT_INF(*ret, "selected slot by LRU, t_last = %" PRId64 "\n", t_last);
        update_cache = true;
    }
}
```

### 2. Common Prefix Computation: `get_common_prefix()` (server-common.cpp:471)

Handles both plain tokens and multimodal (vision/audio) chunks:

```cpp
size_t server_tokens::get_common_prefix(const server_tokens & b) const {
    const size_t max_idx = std::min(tokens.size(), b.tokens.size());

    if (!has_mtmd) {
        for (size_t i = 0; i < max_idx; ++i) {
            if (tokens[i] == b.tokens[i]) {
                continue;
            }
            return i;
        }
        return max_idx;
    }

    // multimodal: LLAMA_TOKEN_NULL markers indicate media chunks
    for (size_t i = 0; i < max_idx; ++i) {
        const llama_token ai =   tokens[i];
        const llama_token bi = b.tokens[i];

        if (ai == LLAMA_TOKEN_NULL && bi == LLAMA_TOKEN_NULL) {
            const auto & a_chunk =   find_chunk(i);
            const auto & b_chunk = b.find_chunk(i);
            const std::string id_ai = mtmd_input_chunk_get_id(a_chunk.get());
            const std::string id_bi = mtmd_input_chunk_get_id(b_chunk.get());
            const size_t n_tok_a = mtmd_input_chunk_get_n_tokens(a_chunk.get());
            const size_t n_tok_b = mtmd_input_chunk_get_n_tokens(b_chunk.get());

            if (id_ai == id_bi && n_tok_a == n_tok_b) {
                i += n_tok_a - 1;
                continue;
            }
            return i;
        }

        if (ai == bi) continue;
        return i;
    }
    return max_idx;
}
```

### 3. Cache Save/Load on Slot Reuse (server-context.cpp:1620)

When a slot is reused and `update_cache` is true:

```cpp
if (update_cache) {
    SRV_TRC("%s", "updating prompt cache\n");
    const int64_t t_start = ggml_time_us();

    ret->prompt_save(*prompt_cache);   // save old slot content to external cache

    if (!ret->prompt_load(*prompt_cache, task.tokens)) {
        ret->prompt_clear();           // load best cached entry; if none, clear
    }

    prompt_cache->update();            // evict oldest entries if over limit

    SRV_TRC("prompt cache update took %.2f ms\n", (ggml_time_us() - t_start) / 1000.0);
}
```

### 4. External Cache Load: `server_prompt_cache::load()` (server-task.cpp:1737)

Searches the external cache for a better match than the slot's current prompt:

```cpp
bool server_prompt_cache::load(server_prompt & prompt, const server_tokens & tokens_new,
                                llama_context * ctx_tgt, llama_context * ctx_dft, int32_t id_slot) {
    const int lcp_best = prompt.tokens.get_common_prefix(tokens_new);

    float f_keep_best = prompt.tokens.size() > 0 ? float(lcp_best) / prompt.tokens.size() : -1.0f;
    float sim_best    = float(lcp_best) / tokens_new.size();

    auto it_best = states.end();

    for (auto it = states.begin(); it != states.end(); ++it) {
        const int lcp_cur = it->prompt.tokens.get_common_prefix(tokens_new);
        const float f_keep_cur = float(lcp_cur) / it->prompt.tokens.size();
        const float sim_cur    = float(lcp_cur) / tokens_new.size();

        // don't trash large prompts — skip entries where <25% would be preserved
        if (f_keep_cur < 0.25f) {
            continue;
        }

        if (f_keep_best < f_keep_cur && sim_best < sim_cur) {
            f_keep_best = f_keep_cur;
            sim_best    = sim_cur;
            it_best = it;
        }
    }

    if (it_best != states.end()) {
        // restore KV state from cached entry into the slot
        auto & data = it_best->data.main;
        const size_t n = llama_state_seq_set_data_ext(ctx_tgt, data.data(), data.size(), id_slot, 0);
        // ... draft model state restoration ...
        prompt = std::move(it_best->prompt);
        states.erase(it_best);
    }
    return true;
}
```

