Now for the full answer — here's how prompt cache / slot reuse works, centered on the common-prefix matching:

## Two layers of reuse

### Layer 1 — In-slot KV reuse via `n_past`

When a slot already holds a prompt, the inference loop reuses the cached KV by computing the longest common prefix between the slot's existing prompt and the new input:

```cpp
// server-context.cpp:3154
if (slot.task->params.cache_prompt) {
    // reuse any previously computed tokens that are common with the new prompt
    n_past = slot.prompt.tokens.get_common_prefix(input_tokens);
```

`n_past` tells the decoder how many tokens are already in the KV cache and don't need re-computation.

### Layer 2 — Cross-slot prompt cache (`server_prompt_cache`)

When a slot is **reassigned** to a new task, `get_available_slot()` decides whether to save the slot's current prompt to an external cache and load a better-matching one:

```cpp
// server-context.cpp:1530
server_slot * get_available_slot(const server_task & task) {
    server_slot * ret = nullptr;
    bool update_cache = false;

    // --- Strategy 1: explicit slot ID ---
    if (task.id_slot != -1) {
        ret = get_slot_by_id(task.id_slot);
    }

    // --- Strategy 2: LCP similarity (controlled by --slot-prompt-similarity) ---
    if (slot_prompt_similarity != 0.0f) {
        float sim_best = 0;
        for (server_slot & slot : slots) {
            if (slot.is_processing() || slot.prompt.tokens.empty()) continue;

            // fraction of LCP length vs input prompt length
            const float sim_cur = float(tokens.get_common_prefix(task.tokens)) / task.tokens.size();

            if (sim_cur > sim_best && sim_cur > slot_prompt_similarity) {
                sim_best = sim_cur;
                ret = &slot;
            }
        }
        if (ret != nullptr) {
            const float f_keep = (sim_best * task.tokens.size()) / ret->prompt.tokens.size();
            // if we'd lose >50% of existing context, save it to the external cache first
            if (f_keep < 0.5f) {
                update_cache = true;
            }
        }
    }

    // --- Strategy 3: LRU fallback ---
    if (ret == nullptr) {
        for (server_slot & slot : slots) {
            if (slot.is_processing()) continue;
            if (!ret || slot.t_last_used <= t_last) {
                t_last = slot.t_last_used;
                ret = &slot;
            }
        }
        if (ret) update_cache = true;
    }

    // --- Save current slot state, then try to load a better match ---
    if (ret && update_cache && prompt_cache && task.type == SERVER_TASK_TYPE_COMPLETION) {
        ret->prompt_save(*prompt_cache);                        // serialize current KV to cache
        if (!ret->prompt_load(*prompt_cache, task.tokens)) {    // search cache for better match
            ret->prompt_clear();                                // nothing better found → start fresh
        }
        prompt_cache->update();                                 // evict old entries if over limit
    }
    return ret;
}
```

### The external cache search (`server_prompt_cache::load`)

```cpp
// server-task.cpp:1737
bool server_prompt_cache::load(server_prompt & prompt, const server_tokens & tokens_new, ...) {
    // baseline: the slot's current prompt
    const int lcp_best = prompt.tokens.get_common_prefix(tokens_new);
    float f_keep_best = prompt.tokens.size() > 0 ? float(lcp_best) / prompt.tokens.size() : -1.0f;
    float sim_best    = float(lcp_best) / tokens_new.size();

    // scan all cached states for a better match
    for (auto it = states.begin(); it != states.end(); ++it) {
        const int lcp_cur = it->prompt.tokens.get_common_prefix(tokens_new);
        const float f_keep_cur = float(lcp_cur) / it->prompt.tokens.size();
        const float sim_cur    = float(lcp_cur) / tokens_new.size();

        // discard entries that would discard too much of their own context
        if (f_keep_cur < 0.25f) continue;

        // must improve BOTH metrics simultaneously
        if (f_keep_best < f_keep_cur && sim_best < sim_cur) {
            f_keep_best = f_keep_cur;
            sim_best    = sim_cur;
            it_best = it;
        }
    }
    // ... restore KV state from it_best into the slot's llama_context ...
}
```

